INSERT INTO blind_box(name,series,image,description,price,stock,status,creator_id,create_request_id,create_payload_hash) SELECT '深海来信','sea','/images/sea.png','把海洋的温柔，装进小小的收藏。',5900,100,'ON_SALE',@actor,'fixture-sea','development-fixture' WHERE @actor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM blind_box WHERE creator_id=@actor AND create_request_id='fixture-sea');
INSERT INTO prize(blind_box_id,prize_name,prize_img,rarity,value,stock) SELECT @box,'海豚','/images/dolphin.png','common',0,30 WHERE @box IS NOT NULL AND NOT EXISTS(SELECT 1 FROM prize WHERE blind_box_id=@box AND prize_name='海豚');
INSERT INTO stock_ledger(blind_box_id,prize_id,actor_id,delta,stock_after,reason,request_id) SELECT @box,p.id,@actor,30,30,'INITIAL','fixture-sea' FROM prize p WHERE p.blind_box_id=@box AND p.prize_name='海豚' AND NOT EXISTS(SELECT 1 FROM stock_ledger s WHERE s.blind_box_id=@box AND s.prize_id=p.id AND s.reason='INITIAL' AND s.request_id='fixture-sea');
