-- Development fixtures only. Requires at least one ADMIN user; never imported automatically.
SET @actor = (SELECT MIN(id) FROM user WHERE role='ADMIN');
START TRANSACTION;
SET @box=(SELECT id FROM blind_box WHERE creator_id=@actor AND create_request_id='fixture-sea');
SET @box=(SELECT id FROM blind_box WHERE creator_id=@actor AND create_request_id='fixture-forest');
SET @box=(SELECT id FROM blind_box WHERE creator_id=@actor AND create_request_id='fixture-space');
SET @box=(SELECT id FROM blind_box WHERE creator_id=@actor AND create_request_id='fixture-candy');
COMMIT;
SELECT COUNT(*) AS configured_fixture_boxes FROM blind_box WHERE create_payload_hash='development-fixture';
